library(shiny)
library(bslib)
library(dplyr)
library(shinyWidgets)

ui <- fluidPage(
    theme = bslib::bs_theme(version = "5", bootswatch = "superhero"),
    hr(),
    titlePanel("MDR4T: MDR-TB Guide for Thai"),
    mainPanel(
        fluidRow(
            hr()
        ),
        p("โปรแกรมช่วยเลือกสูตรการรักษาวัณโรคปอดดื้อยา"),
        hr(),
        fluidRow(
            h3(style="color:cyan;font-size:1.2em","ยาที่ดื้อ")), 
        fluidRow(
            checkboxInput("H", "Isoniazid (H)", value = FALSE)), 
        fluidRow(checkboxInput("R", "Rifampicin (R)", value = FALSE)),
        fluidRow(radioGroupButtons("Q", "Fluoroquinolone (FQ)",  selected = NULL,
                               choices = c("not known", "resist", "not resist"))),
        conditionalPanel(
            condition = "input.Q == 'resist'", 
            checkboxInput("A", "Group A (Bedaquiline หรือ Linezolid)", value = FALSE)
        ),
        fluidRow(
            hr()
        ),
        fluidRow(
            h3(style="color:cyan;font-size:1.2em","ลักษณะผู้ป่วย"),
            checkboxInput("kid", "อายุน้อยกว่า 14 ปี"),
            checkboxInput("pregnant", "ต้ังครรภ์ / ให้นมบุตร"),
         ),
        card(
            card_header(style="color:cyan;font-size:1.2em","รูปแบบการดื้อยา"),
            textOutput("Rpattern")
        ),
        card(
            card_header(style="color:cyan;font-size:1.2em","สูตรยาที่แนะนำ"),
            textOutput("formula")
        ),
        radioGroupButtons("seedose", "ดูขนาดยา/กลุ่มยา", selected = NULL, 
                     choices = c("no", "yes")),
        conditionalPanel(
            condition = "input.seedose == 'yes'",
            card(
                card_header(style="color:cyan;font-size:1.2em","ขนาดยา (ผู้ใหญ่)"),
                p("B = Bedaquiline (100 mg)-- 400 mg/day for 2 weeks then 200 mg/day 3 times/week or 200 mg/day 
                for 8 weeks then 100 mg/day"),
                p("Pa = Pretomanid (200 mg)-- 200 mg/day"),
                p("L = Linezolid (600 mg)-- 600 mg/day, can be reduced (300 mg/day) depending on tolerability"),
                p("M = Moxifloxacin (400 mg)-- 400 mg/day"),
                p("Lfx = Levofloxacin (750 mg)-- 750-1,000 mg/day"),
                p("C = Clofazimine (100 mg)-- 100 mg/day"),
                p("E = Ethambutol (400 mg)-- 1,200-1,600 mg/day"),
                p("D = Delamanid (50 mg)-- 1 tab BD for <46 kgBW & 2 tab BD for >46 kgBW"),
                p("Z = Pyrazinamide (500 mg)-- 1,500-2,000 mg/day"),
                p("Eto/Pto = Etionamide/Protionamide (250 mg)-- 750 mg for <70 kgBW and 1,000 mg for >70 kgBW")
                ),
            card(
                card_header(style="color:cyan;font-size:1.2em","กลุ่มยาสำหรับ 9-month  regimens"),
                p("ใช้เป็นทางเลือก กรณีที่ไม่ดื้อต่อยา Quinolones"),
                p("BLMZ"),
                p("BLLfxCZ"),
                p("BDLLfxZ"),
                p("DCLLfxZ"),
                p("DCMZ")
            ),
            card(
            card_header(style="color:cyan;font-size:1.2em","กลุ่มยาสำหรับ Longer regimens"),
            p(style="color:cyan;font-size:0.9em", "Group A:"), 
            p(style="font-size:0.9em", "[เลือก 3 ขนาน]"),
            p(style="font-size:0.8em", "Lfx: levofloxacin / M: moxifloxacin; B: bedaquiline; 
              L: linezolid"),
            p(style="color:cyan;font-size:0.9em","Group B:"),
            p(style="font-size:0.9em", "[เลือกเพิ่ม 1-2 ขนาน]"),
            p(style="font-size:0.8em","C: clofazimine; Cs/Trd: cycloserine/Terizidone"),
            p(style="color:cyan;font-size:0.9em","Group C:"),
            p(style="font-size:0.9em", "[เลือกเพิ่มเพื่อให้ครบ หรือ เมื่อไม่สามารถใช้ยากลุ่มที่ 1 และ 2]"),
            p(style="font-size:0.8em","E: ethambutol; D: delamanid; Z: pyrazinamide; 
            Ipm-Cln: imipenem-cilastatin / Mpm: meropenem; Am: amikacin; 
            Pto: protionamide / Eto: ethionamide; PAS: p-aminosalicylic acid")
            ),
            ),
        fluidRow(
            p(style="font-size:0.8em","แหล่งข้อมูล: WHO Operational Handbook on Tuberculosis: 
            Module 4: Treatment and Care. 2025.")
            ),
        fluidRow(
            hr()
            ),
        fluidRow(
            p(style="font-size:0.8em", "คำเตือน: เหมาะสำหรับผู้ประกอบวิชาชีพเวชกรรมเท่าน้ัน ผู้พัฒนาขอสงวนสิทธิ์ที่จะไม่รับผิดชอบต่อความเสียหายที่เกิดขึ้นจากการใช้โปรแกรมนี้")
            ),
        fluidRow(
            hr()
            ),
        fluidRow(
            p(style="font-size:0.8em", "June 2026")
            ),
        fluidRow(
            hr()
            )
        )
    )

# --- Server Section ---
server <- function(input, output, session)
    observe({
    output$Rpattern <- renderText({
        if (input$H == TRUE & input$R == FALSE)
            {Rpattern <- "Rifampicin-susceptible, INH-resistant (Hr-TB)"} 
        #MDR/RR
        else if (input$H == FALSE & input$R == TRUE & input$Q == "not resist")
        {Rpattern <- "RR-TB"} 
        else if (input$H == FALSE & input$R == TRUE & input$Q == "not known")
        {Rpattern <- "RR-TB, FQ susceptibility pending"} 
        else if (input$H == TRUE & input$R == TRUE & input$Q == "not resist")
        {Rpattern <- "MDR-TB"}
        else if (input$H == TRUE & input$R == TRUE & input$Q == "not known")
        {Rpattern <- "MDR-TB, FQ susceptibility pending"}        
        else if (input$R == TRUE & input$Q == "resist" & input$A == FALSE)
            {Rpattern <- "Pre-XDR-TB"}
        else if (input$R == TRUE & input$Q == "resist" & input$A == TRUE)
            {Rpattern <- "XDR-TB"}
    })
    output$formula <- renderText({
        #INH resistance
        if (input$H == TRUE & input$R == FALSE & (input$Q == "not resist"|input$Q == "not known") &
            input$pregnant == FALSE)
            {formula <- "6REZLfx หรือ 6(H)REZLfx (กรณีเป็นยาผสม)"}
        else if (input$H == TRUE & input$R == FALSE & (input$Q == "resist"))
            {formula <- "6REZ หรือ 6(H)REZ (กรณีเป็นยาผสม)" }        
        else if (input$H == TRUE & input$R == FALSE & (input$Q == "not resist"|input$Q == "not known")
                 & input$pregnant == TRUE)
            {formula <- "6REZLfx หรือ 6(H)REZLfx (กรณีเป็นยาผสม)"}
        #MDR/RR
        else if (input$R == TRUE & input$Q == "not resist" & input$A == FALSE &
            input$kid == FALSE & input$pregnant == FALSE)
        {formula <- "6BPaLM"}
        else if (input$R == TRUE & input$Q == "not known" & input$A == FALSE &
            input$kid == FALSE & input$pregnant == FALSE)
        {formula <- "6BPaLM"}
        else if (input$R == TRUE & input$Q == "not known" & input$A == TRUE &
                 input$kid == FALSE & input$pregnant == FALSE)
        {formula <- "6BPaLM"}
        else if (input$R == TRUE & input$Q == "not resist" & input$A == TRUE &
                 input$kid == FALSE & input$pregnant == FALSE)
        {formula <- "6BPaLM"}              
        else if (input$R == TRUE & input$Q == "not resist" & input$A == FALSE &
                 input$kid == TRUE)
        {formula <- "6BDLLfx"} 
        else if (input$R == TRUE & input$Q == "not resist" & input$A == TRUE &
                 input$kid == TRUE)
        {formula <- "6BDLLfx"}         
        else if (input$R == TRUE & input$Q == "not known" & input$A == FALSE &
                 input$kid == TRUE)
        {formula <- "6BDLLfx"}         
        else if (input$R == TRUE & input$Q == "not resist" & input$A == FALSE &
                 input$pregnant == TRUE)
        {formula <- "6BDLLfx"}
        else if (input$R == TRUE & input$Q == "not resist" & input$A == TRUE &
                 input$pregnant == TRUE)
        {formula <- "6BDLLfx"}        
        else if (input$R == TRUE & input$Q == "not known" & input$A == FALSE &
                 input$pregnant == TRUE)
        {formula <- "6BDLLfx"}
        else if (input$R == TRUE & input$Q == "not known" & input$A == TRUE &
                 input$pregnant == TRUE)
        {formula <- "6BDLLfx"}
        else if (input$R == TRUE & input$Q == "not known" & input$A == TRUE &
                 input$kid == TRUE)
        {formula <- "6BDLLfx"}                
        else if (input$H == TRUE & input$R == TRUE & input$Q == "not known" &
                 input$pregnant == TRUE)
        {formula <- "6BDLLfx"}  
        else if (input$H == TRUE & input$R == TRUE & input$Q == "not resist" &
                 input$pregnant == TRUE)
        {formula <- "6BDLLfx"}          
        else if (input$H == TRUE & input$R == TRUE & input$Q == "not known" &
                 input$kid == TRUE)
        {formula <- "6BDLLfx"}  

        #Pre-XDR
        else if (input$R == TRUE & input$Q == "resist" & input$A == FALSE &
                 input$kid == FALSE & input$pregnant == FALSE)
        {formula <- "6BPAL"}
        else if (input$R == TRUE & input$Q == "resist" & input$A == FALSE &
                 input$kid == TRUE)
        {formula <- "6BDLC"}
        else if (input$R == TRUE & input$Q == "resist" & input$A == FALSE &
                 input$pregnant == TRUE)            
        {formula <- "6BDLC"}
        #XDR
        else if (input$R == TRUE & input$Q == "resist" & input$A == TRUE)            
        {formula <- "Longer 18-m regimen"}      
    })
    })

shinyApp(ui, server)
